const webhookBody = $('Webhook').first().json.body;
const conhecimento = $('Config e conhecimento').first().json.conhecimento;
const conversa = $input.first().json; // saída de "Buscar conversa"

// Monta o histórico em mensagens user/assistant para a Anthropic. Áudio e figurinha viram um aviso
// em texto (o bot não vê mídia, igual ao agente interno). Envio que falhou não chegou ao cliente,
// então fica de fora.
const historico = (conversa.mensagens || [])
  .filter((mensagem) => !(mensagem.direcao === 'enviada' && mensagem.status === 'falhou'))
  .map((mensagem) => {
    let texto = mensagem.texto;
    if (mensagem.tipo === 'audio') texto = '[cliente enviou um áudio]';
    if (mensagem.tipo === 'figurinha') texto = '[cliente enviou uma figurinha]';
    // Marca que a imagem já foi mandada: o bot vê isso e não manda de novo.
    if (mensagem.tipo === 'imagem') texto = `[imagem enviada]${texto ? '\n' + texto : ''}`;
    return {
      role: mensagem.direcao === 'recebida' ? 'user' : 'assistant',
      content: texto || '(mensagem vazia)',
    };
  });

// A Anthropic exige alternância estrita user/assistant, começando em user: junta mensagens seguidas
// do mesmo papel em vez de mandar duas do mesmo lado em sequência.
const mensagens = [];
for (const linha of historico) {
  const ultima = mensagens[mensagens.length - 1];
  if (ultima && ultima.role === linha.role) ultima.content += '\n' + linha.content;
  else mensagens.push({ ...linha });
}
if (mensagens.length === 0 || mensagens[0].role !== 'user') {
  // A conversa costuma abrir com o nosso disparo; a Anthropic exige que comece pelo cliente.
  mensagens.unshift({ role: 'user', content: '[início da conversa]' });
}

// Alguém (equipe ou outra execução) já respondeu depois da última mensagem do cliente: não há o que
// responder. Além disso, o modelo recusa (400) uma conversa que termina em mensagem do assistant.
if (mensagens[mensagens.length - 1].role !== 'user') return [];

// Dois blocos: o primeiro (base de conhecimento + regras) é igual em toda chamada e fica em cache por
// 1 hora, cobrado a ~10% do preço nas leituras; o nome do cliente muda por conversa, então vem depois,
// fora do cache — se viesse antes, cada cliente teria um cache só dele.
const system = [
  {
    type: 'text',
    text: `${conhecimento}

Quando puder responder, escreva só o texto da mensagem para o cliente — direto, sem introdução nem comentário.
Quando precisar de uma pessoa da equipe (ver "Situações que o bot não resolve sozinho"), responda EXATAMENTE neste formato, nada mais:
HUMANO: <motivo em uma frase>

Quando for apresentar os planos (preços e o que cada um inclui), comece a resposta com a linha [IMAGEM:planos] sozinha: a tabela com os três planos vai anexada e o seu texto vira a legenda, então resuma em até 900 caracteres, sem repetir tudo o que a imagem já mostra. Mande essa imagem só uma vez por conversa: se o histórico já tem [imagem enviada], responda só com texto.`,
    cache_control: { type: 'ephemeral', ttl: '1h' },
  },
  {
    type: 'text',
    text: `Nome do cliente, se você souber (pode não ser real, é o que a pessoa colocou no WhatsApp dela): ${conversa.nome || 'desconhecido'}`,
  },
];

return [
  {
    json: {
      telefone: webhookBody.telefone,
      numeroId: webhookBody.numeroId,
      system,
      messages: mensagens,
      // "Extrair resposta" usa para não mandar a imagem dos planos duas vezes na mesma conversa.
      imagemJaEnviada: (conversa.mensagens || []).some((mensagem) => mensagem.tipo === 'imagem' && mensagem.status !== 'falhou'),
    },
  },
];

const resposta = $input.first().json;
const bloco = (resposta.content || []).find((b) => b.type === 'text');
const bruto = ((bloco && bloco.text) || '').trim();

// [IMAGEM:nome] no texto pede para anexar uma imagem cadastrada no Allp Chat (Configurações → Imagens do
// agente). O marcador sai do texto; o nome vai no campo "imagem".
const marcador = bruto.match(/\[IMAGEM:([a-z0-9_-]+)\]/i);
const texto = bruto.replace(/\[IMAGEM:[a-z0-9_-]+\]\s*/gi, '').trim();

// Rede de segurança: se o bot apresentou os planos (citou 2 ou mais dos preços) sem usar o marcador,
// a tabela vai anexada do mesmo jeito — uma vez por conversa.
const PRECOS_DOS_PLANOS = ['129,90', '164,90', '219,90'];
const citouOsPlanos = PRECOS_DOS_PLANOS.filter((preco) => texto.includes(preco)).length >= 2;
const imagemJaEnviada = $('Montar mensagens').first().json.imagemJaEnviada;
const imagem = marcador ? marcador[1].toLowerCase() : citouOsPlanos && !imagemJaEnviada ? 'planos' : null;

const telefone = $('Montar mensagens').first().json.telefone;
const numeroId = $('Montar mensagens').first().json.numeroId;

const humano = (motivo) => [{ json: { modo: 'humano', telefone, numeroId, motivo } }];

if (resposta.stop_reason === 'refusal') return humano('O modelo recusou responder esta conversa.');
if (!texto) return humano('O bot não conseguiu gerar uma resposta.');
if (texto.startsWith('HUMANO:')) {
  return humano(texto.slice('HUMANO:'.length).trim() || 'O bot pediu atendimento humano.');
}

return [{ json: { modo: 'resposta', telefone, numeroId, texto, imagem } }];
